"OLAYLAR_T5_1000A:1150-01-01:0":{"b": ["السلطان مسعود يعطي الحلة لسالار كرد", "4bdbd034"], "d": ["بعد وفاة المزيدي علي أعطى السلطان مسعود الحلة لقائده سالار كرد.", "059e9aeb"]},
"OLAYLAR_T5_1000A:1152-01-01:0":{"b": ["وفاة السلطان مسعود؛ الخليفة المقتفي ينفرد بحكم العراق ويستولي على الحلة والكوفة وواسط", "21192405"], "d": ["بوفاة السلطان مسعود أقام الخليفة المقتفي لأمر الله في بغداد والعراق حكمًا مستقلًا عن النفوذ السلجوقي؛ واستولى وزير الخليفة على الحلة، وضُمّت الكوفة وواسط أيضًا.", "cd348b82"]},
"OLAYLAR_T5_1000A:1156-01-01:0":{"b": ["يغي باسان يستولي على ألبستان", "824708d3"], "d": ["بعد وفاة مسعود استولى يغي باسان، ملك الدانشمنديين في سيواس، على ألبستان؛ وتُرك له حكمها بموجب اتفاق.", "d413e508"]},
"OLAYLAR_T5_1000A:1156-01-01:1":{"b": ["القادة السلاجقة يستولون على الحلة، والمزيديون تابعون للنائب", "43afd955"], "d": ["استولى قادة السلطان محمد بن محمود على الحلة؛ واستمر المزيديون في الحكم تابعين لنائب السلطان.", "c6c81147"]},
"OLAYLAR_T5_1000A:1160-01-01:0":{"b": ["باكو تحت حكم الشروانشاهيين — شهادة مؤرخة في المصدر", "1f2863e4"], "d": ["يُظهر المصدر مدينة باكو في هذا التاريخ تحت إدارة الشروانشاهيين؛ أما ملكيتها قبل ذلك فغير مؤرخة في المصدر (يترك الأطلس ما قبل هذا التاريخ فارغًا).", "506dae86"]},
"OLAYLAR_T5_1000A:1163-01-01:0":{"b": ["الخليفة المستنجد يستولي على الحلة وينتهي المزيديون", "4348923c"], "d": ["احتلت قوات الخليفة المستنجد وبنو منتفق الحلة، وجرى تفريق المزيديين.", "da071466"]},
